 const adopt=()=>{expected=a?.work;workBytes=JSON.stringify(expected);sourceBytes=JSON.stringify(source);rawRoot=book.sharedPointSheets;rawBytes=JSON.stringify(rawRoot);rootPresent=Object.hasOwn(book,'sharedPointSheets');};
 const guard=n=>{parents.set(n,ancestry(n));for(const type of ['click','input','change','toggle','keydown','focusin'])n.addEventListener(type,e=>{if(!live(n)){e.preventDefault();e.stopImmediatePropagation();}},true);};guard(root);root.querySelectorAll('button,a,select,details,summary,svg').forEach(guard);
 const focus=selector=>{const currentRoot=document.querySelector('[data-sp-root]'),node=currentRoot?.querySelector(selector);(node&&!node.disabled?node:currentRoot?.querySelector('#sp-title'))?.focus({preventScroll:true});};const redraw=(selector='#sp-title')=>{ctx.render?.();focus(selector);};
 const folds=()=>{v.chooseOpen=!!root.querySelector('[data-sp-chooser]')?.open;if(a)root.querySelectorAll('[data-sp-fold]').forEach(n=>{a.folds[n.dataset.spFold]=n.open;});};
 const clear=()=>{if(a)a.status='';const status=root.querySelector('#sp-status');if(status)status.textContent='';};
