 function on(selector,fn,target='#sp-title'){root.querySelectorAll(selector).forEach(n=>n.addEventListener('click',()=>{if(!live(n)||n.disabled||n.getAttribute('aria-disabled')==='true')return;folds();clear();stopSpeech();if(fn(n)!==false)redraw(typeof target==='function'?target(n):target);}));}
 function change(action,value){if(screen!=='draft'||!a)return false;const next=changeSharedPointWork(source,a.work,action,value);if(!next)return false;a.work=next;adopt();return true;}
 const chooseDraft=()=>{const prior=[...v.drafts].findLast(([,draft])=>draft.caseId===v.caseId&&draft.shift===v.shift);if(prior){v.key=prior[0];v.screen='draft';v.card=null;}else fresh(v);};
