 for(const axis of ['x','y'])root.querySelector(`[data-sp-${axis}]`)?.addEventListener('change',e=>{const n=e.currentTarget;if(!live(n)||n.disabled)return;folds();clear();stopSpeech();if(change(axis,Number(n.value)))redraw(`[data-sp-${axis}]`);});
 root.querySelector('[data-sp-claim]')?.addEventListener('change',e=>{const n=e.currentTarget;if(!live(n)||n.disabled)return;folds();clear();stopSpeech();if(change('claim',n.value||null))redraw('[data-sp-claim]');});
 on('[data-sp-reference]',()=>change('reference'),'#sp-reference-title');
 root.querySelector('[data-sp-plot]')?.addEventListener('click',e=>{const svg=e.currentTarget;if(!live(svg)||screen!=='draft'||!a)return;const matrix=svg.getScreenCTM();if(!matrix)return;const p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;const local=p.matrixTransform(matrix.inverse()),snap=(value,min,max)=>Math.max(min,Math.min(max,Math.round(value*2)/2));folds();clear();stopSpeech();const x=snap((local.x-62)/63.5-4,-4,4),y=snap(6-(local.y-32)*12/568,-6,6);if(!change('x',x)||!change('y',y))return;redraw('[data-sp-x]');});
 for(const [selector,fn]of [['[data-sp-case]',n=>{if(!sharedPointCases.some(c=>c.id===n.value))return false;v.caseId=n.value;chooseDraft();}],['[data-sp-shift]',n=>{if(![-1,0,1].includes(Number(n.value)))return false;v.shift=Number(n.value);chooseDraft();}],['[data-sp-draft]',n=>{if(!v.drafts.has(n.value))return false;v.key=n.value;v.screen='draft';v.card=null;}]])root.querySelector(selector)?.addEventListener('change',e=>{const n=e.currentTarget;if(!live(n)||n.disabled||n.getAttribute('aria-disabled')==='true')return;folds();clear();stopSpeech();if(fn(n)!==false)redraw(selector);});
